INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4967411, 721797, 47316, '<td valign="top">holy wow! great find! I don''t see what is going on with that tree! lol. I feel like the tone and lack of contrast will bring down the score on this one. If you could have darkened the tree trucks to make the letters stand out more and provide more contrast I think I would be a better shot.</td>', 'holy wow! great find! I don''t see what is going on with that tree! lol. I feel like the tone and lack of contrast will bring down the score on this one. If you could have darkened the tree trucks to make the letters stand out more and provide more contrast I think I would be a better shot.', '2008-09-22 01:20:57.000000', NULL, 1),
(4967417, 722485, 47316, '<td valign="top">very catchy colors!</td>', 'very catchy colors!', '2008-09-22 01:23:44.000000', NULL, 1),
(4967425, 723568, 47316, '<td valign="top">very nice find! love the textures and bokeh in the background. I think the focus is throwing me... like my eyes expect it to be in the center but its more like in the bottom left corner. In any case, great shot!</td>', 'very nice find! love the textures and bokeh in the background. I think the focus is throwing me... like my eyes expect it to be in the center but its more like in the bottom left corner. In any case, great shot!', '2008-09-22 01:26:19.000000', NULL, 1),
(4967429, 723496, 77521, '<td valign="top">awesome shot! this really stooD out to me!!</td>', 'awesome shot! this really stooD out to me!!', '2008-09-22 01:28:03.000000', NULL, 1),
(4967430, 723542, 47316, '<td valign="top">wow I really liked the shot and then I saw the horses and liked it even more. What a brilliantly captured moment. I would almost say it doesn''t work for the challenge except for the fact that the bow is so perfect I can almost imagine the full circle...</td>', 'wow I really liked the shot and then I saw the horses and liked it even more. What a brilliantly captured moment. I would almost say it doesn''t work for the challenge except for the fact that the bow is so perfect I can almost imagine the full circle...', '2008-09-22 01:28:05.000000', NULL, 1),
(4967434, 723747, 47316, '<td valign="top">wow. very pretty, simple and understated shot. Love the little heart next to the Y. The colors are great!</td>', 'wow. very pretty, simple and understated shot. Love the little heart next to the Y. The colors are great!', '2008-09-22 01:29:31.000000', NULL, 1),
(4967440, 722595, 47316, '<td valign="top">Cool coloration. It kind of reminds me of the beginning of the Wizard of Oz.</td>', 'Cool coloration. It kind of reminds me of the beginning of the Wizard of Oz.', '2008-09-22 01:32:00.000000', NULL, 1),
(4967442, 723451, 40718, '<td valign="top">I got last week wrong, but I''m pretty sure I need to say Hi Irene in this one...</td>', 'I got last week wrong, but I''m pretty sure I need to say Hi Irene in this one...', '2008-09-22 01:32:23.000000', NULL, 1),
(4967443, 723589, 47316, '<td valign="top">pretty nice! At first this photo struck me as odd and then I realized it was because I don''t think I''ve seen a mantis in such a pretty setting before. It''s almost like a contradiction. Very cool shot, and its a mighty fine b!</td>', 'pretty nice! At first this photo struck me as odd and then I realized it was because I don''t think I''ve seen a mantis in such a pretty setting before. It''s almost like a contradiction. Very cool shot, and its a mighty fine b!', '2008-09-22 01:33:14.000000', NULL, 1),
(4967446, 722715, 50641, '<td valign="top">haha :)</td>', 'haha :)', '2008-09-22 01:33:38.000000', NULL, 1),
(4967449, 723055, 36371, '<td valign="top">This seems out of focus.</td>', 'This seems out of focus.', '2008-09-22 01:34:43.000000', NULL, 1),
(4967453, 723719, 50641, '<td valign="top">the score is MooT :)  nice detail !</td>', 'the score is MooT :)  nice detail !', '2008-09-22 01:35:15.000000', NULL, 1),
(4967464, 723460, 38032, '<td valign="top">cool - kinda creepy the way the swings are blowing in the wind?</td>', 'cool - kinda creepy the way the swings are blowing in the wind?', '2008-09-22 01:38:52.000000', NULL, 1),
(4967466, 723668, 15711, '<td valign="top">Not that I care, but I would have inverted it so that the C''s are truly that shape. I like it fine, but DPC voters are VERY literal. :~)  Good luck. 7</td>', 'Not that I care, but I would have inverted it so that the C''s are truly that shape. I like it fine, but DPC voters are VERY literal. :~)  Good luck. 7', '2008-09-22 01:39:58.000000', NULL, 1),
(4967467, 722715, 93421, '<td valign="top">Very clever title!</td>', 'Very clever title!', '2008-09-22 01:41:38.000000', NULL, 1),
(4967491, 722485, 54645, '<td valign="top">Creepy spider, in this version, the background is quite distracting (orange stripe)</td>', 'Creepy spider, in this version, the background is quite distracting (orange stripe)', '2008-09-22 02:07:42.000000', NULL, 1),
(4967492, 723389, 54645, '<td valign="top">Too bad it''s OOF. Good thought, clearly an S</td>', 'Too bad it''s OOF. Good thought, clearly an S', '2008-09-22 02:08:21.000000', NULL, 1),
(4967512, 723451, 79955, '<td valign="top">Nice &amp; simple. Good job, 7</td>', 'Nice & simple. Good job, 7', '2008-09-22 02:55:07.000000', NULL, 1),
