(4968563, 723168, 94265, '<td valign="top">Good find, for me this is one of the better shots in the challenge. Great lighting and crop. I might have moved those few stray bits of twig out of the way.</td>', 'Good find, for me this is one of the better shots in the challenge. Great lighting and crop. I might have moved those few stray bits of twig out of the way.', '2008-09-22 14:59:10.000000', NULL, 1),
(4968565, 723735, 94265, '<td valign="top">Great macro shot and fantastic colours. He looks like he''s wearing a little jacket! 8.</td>', 'Great macro shot and fantastic colours. He looks like he''s wearing a little jacket! 8.', '2008-09-22 14:59:58.000000', NULL, 1),
(4968566, 722322, 9462, '<td valign="top">I like the way you''ve brought the foreground and background together... and the way the bushes mimic the mountain scape. Great find and one of the more creative entries of the challenge. Good luck!</td>', 'I like the way you''ve brought the foreground and background together... and the way the bushes mimic the mountain scape. Great find and one of the more creative entries of the challenge. Good luck!', '2008-09-22 15:00:20.000000', NULL, 1),
(4968567, 723600, 94265, '<td valign="top">Lovely tones, would maybe like his ''L'' in a little more focus. Good crop. 7.</td>', 'Lovely tones, would maybe like his ''L'' in a little more focus. Good crop. 7.', '2008-09-22 15:02:10.000000', NULL, 1),
(4968568, 722733, 94265, '<td valign="top">I can make out the A, not very clearly but it''s there. The light and focus on the bird are really good, nice job.</td>', 'I can make out the A, not very clearly but it''s there. The light and focus on the bird are really good, nice job.', '2008-09-22 15:03:04.000000', NULL, 1),
