(4968575, 722485, 94265, '<td valign="top">Brilliantly sharp, clear detail. The green and orange stripes in the background are a tad distracting. 7.</td>', 'Brilliantly sharp, clear detail. The green and orange stripes in the background are a tad distracting. 7.', '2008-09-22 15:07:50.000000', NULL, 1),
(4968576, 723056, 94265, '<td valign="top">Good job spotting this, lovely light too.</td>', 'Good job spotting this, lovely light too.', '2008-09-22 15:08:37.000000', NULL, 1),
